        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.isClosed() && p.contains(date))) {
            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim is dated in a closed period.");
        }
    }
}
-- The periods of a sheet: a name, unique on the sheet without regard to case, and a from and to date,
-- both inclusive. No two periods of a sheet overlap; a claim belongs to the one whose dates contain its date.
CREATE TABLE period (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A period can be closed: its due-total is then fixed at what it was when it closed, and no claim dated in it
-- can change.
ALTER TABLE period ADD COLUMN closed       BOOLEAN       DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
-- A sheet's clerk limit: the highest due a clerk may settle; none means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(12, 2) CHECK (clerk_limit >= 0);

-- The role a user name has on a sheet; a name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward')),
    UNIQUE (sheet_id, user_name)
);

